worker="import datetime,hashlib,json,pathlib,shutil,subprocess,sys\nroot=pathlib.Path.cwd();out=root/'output/session-20261029/native-xml-frame-green';out.mkdir(parents=True,exist_ok=False)\npatch=json.loads((root/'output/session-20261029/native-xml-frame-candidate/patch-receipt.json').read_text())\nif hashlib.sha256((root/'tests/test_xml_frame_documents.py').read_bytes()).hexdigest()!=patch['fixture_sha256']:raise SystemExit('Reviewed XML fixture changed')\nfor name,expected in patch['after'].items():\n if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:raise SystemExit('XML candidate changed: '+name)\ndirty=subprocess.check_output(['git','diff','--name-only','--','src','Makefile','ios'],text=True).splitlines()\nif sorted(dirty)!=sorted(patch['after']):raise SystemExit('Commit or finish other production changes before XML build: '+repr(dirty))\ntracked=subprocess.check_output(['git','ls-files','-z','--','src','Makefile','ios'],text=True).split('\\0')\nsource_hashes={name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in tracked if name and (root/name).is_file()}\n(out/'compiled-source-sha256.json').write_text(json.dumps(source_hashes,indent=2)+'\\n')\nbuild='build-apple-dom-20261029';rows=[]\ndef measured(name,command,duration,marker=None):\n prefix=out/name\n p=subprocess.run(['python3','tools/monitor_process.py','--duration',str(duration),'--settle','0','--output',str(prefix.relative_to(root)),'--',*command],text=True,capture_output=True,timeout=duration+30)\n (out/(name+'-collector.log')).write_text(p.stdout+p.stderr)\n report=json.loads(prefix.with_suffix('.json').read_text());log=prefix.with_suffix('.log').read_text(errors='replace')\n passed=report.get('natural_exit_code')==0 and not report.get('collector_error') and not report.get('ended_by_monitor') and (marker is None or marker in log)\n row={'stage':name,'passed':passed,'exit_code':report.get('natural_exit_code'),'result_lines':[line for line in log.splitlines() if line.startswith('RESULTS')],'interval_cpu_samples':report.get('interval_cpu_samples'),'rss_peak_mib':report.get('rss_peak_mb')};rows.append(row);(out/'stages.json').write_text(json.dumps(rows,indent=2)+'\\n');return passed\ntargets=['lumen','jsrun','test_capture_policy','test_js_device_capabilities','test_frame_removal','test_wasm_async_deadline']\nbuilt=measured('build',['make','-j3','BUILD='+build,'MODE=release','RTC=0','WT=0',*[build+'/'+name for name in targets]],900)\nartifacts={}\nif built:\n for name in targets:\n  binary=root/build/name;sha=hashlib.sha256(binary.read_bytes()).hexdigest();artifacts[name]={'path':str(binary.relative_to(root)),'sha256':sha,'bytes':binary.stat().st_size}\n  if name in ('lumen','jsrun'):\n   snapshot=root/build/(name+'-xml-candidate-'+sha[:16]);shutil.copy2(binary,snapshot)\n   if hashlib.sha256(snapshot.read_bytes()).hexdigest()!=sha:raise SystemExit('XML immutable binary snapshot differs')\n   artifacts[name]['snapshot']=str(snapshot.relative_to(root))\n measured('xml-frame-documents',['python3','tests/test_xml_frame_documents.py','--binary',artifacts['jsrun']['snapshot']],40,'RESULTS xml-frame-documents PASS (24/24 checks)')\n for name,marker in [('test_capture_policy','RESULTS capture-policy PASS (40/40 checks)'),('test_js_device_capabilities','RESULTS js-device-capabilities PASS'),('test_frame_removal','RESULTS frame-removal PASS'),('test_wasm_async_deadline','RESULTS wasm-async-deadline PASS')]:\n  profile=out/(name+'-profile');profile.mkdir();measured(name,['env','LUMEN_PROFILE_DIR='+str(profile),str(root/build/name)],90,marker)\npassed=built and all(row['passed'] for row in rows)\nsummary={'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_base_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'source_manifest':str((out/'compiled-source-sha256.json').relative_to(root)),'build_directory':build,'rtc_enabled':False,'webtransport_enabled':False,'artifacts':artifacts,'stages':rows,'passed':passed,'scope':'Actual Mac native XML/XHTML/SVG frame fixtures, complete script/CSP/inertness controls and existing HTML lifecycle/API/WASM regressions. Full six-file WPT rerun, graphics, hardware capture and iPad are separate gates.'}\nif passed:\n for name,expected in source_hashes.items():\n  if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:raise SystemExit('Compiled source changed while testing: '+name)\n if subprocess.check_output(['git','diff','--cached','--name-only'],text=True).strip():raise SystemExit('Index contains another owner change')\n paths=[*patch['after'],'tests/test_xml_frame_documents.py']\n subprocess.run(['git','diff','--check','--',*paths],check=True)\n subprocess.run(['git','add','--',*paths],check=True)\n subprocess.run(['git','commit','-m','fix: construct XML iframe documents with native realm and parser semantics'],check=True)\n summary['source_commit']=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()\n(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\\n');print(json.dumps(summary));sys.exit(not passed)\n"
